typedef double POLYBENCH_3D(double, MAXGRID, MAXGRID, LENGTH, MAXGRID, MAXGRID);

void kernel_reg_detect(int niter, int maxgrid, int length,
                      POLYBENCH_2D(sum_tang, MAXGRID, MAXGRID, maxgrid, maxgrid),
                      POLYBENCH_2D(mean, MAXGRID, MAXGRID, maxgrid, maxgrid),
                      POLYBENCH_2D(path, MAXGRID, MAXGRID, maxgrid, maxgrid),
                      POLYBENCH_3D(diff, MAXGRID, MAXGRID, LENGTH, maxgrid, maxgrid, length),
                      POLYBENCH_3D(sum_diff, MAXGRID, MAXGRID, LENGTH, maxgrid, maxgrid, length)) {
    int j, i;
    int cnt;

    // Parallelize the outer loop
#pragma omp parallel for private(j, i, cnt)
    for (j = 0; j < maxgrid; ++j) {
        for (i = 0; i < maxgrid; ++i) {
            // First nested loop: replicate summation tangentially across the length dimension
            for (cnt = 0; cnt < length; ++cnt) {
                diff[j][i][cnt] = sum_tang[j][i];
            }

            // Second nested loop: accumulate differences and compute means
            for (cnt = 0; cnt < length; ++cnt) {
                sum_diff[j][i][cnt] += diff[j][i][cnt];

                if (cnt == length - 1) {
                    mean[j][i] = sum_diff[j][i][cnt];
                }
            }

            // Third loop: initialize path with mean values
            if (j == 0) {
                for (cnt = 0; cnt < length; ++cnt) {
                    path[0][i][cnt] = mean[j][i];
                }
            } else {
                for (cnt = 0; cnt < length; ++cnt) {
                    path[j][i][cnt] = path[j-1][i][cnt] + mean[j][i];
                }
            }
        }
    }
