void kernel_jacobi_2d_imper(int tsteps, int n, double** A, double** B) {
    // Initialize B with the initial values from A
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            B[i][j] = A[i][j];
        }
    }

    // Perform Jacobi iterations
