    int i, j;
    double sum, temp;

    // Calculate mean of each column
    #pragma omp parallel for reduction(+:sum)
    for (i = 0; i < m; i++) {
        sum = 0;
        for (j = 0; j < n; j++) {
            sum += data[j][i];
        }
        mean[i] = sum / n;
    }

    // Calculate standard deviation of each column
    #pragma omp parallel for reduction(+:sum)
    for (i = 0; i < m; i++) {
        sum = 0;
        for (j = 0; j < n; j++) {
            sum += pow(data[j][i] - mean[i], 2);
        }
        stddev[i] = sqrt(sum / (n - EPSILON));
    }

    // Center and reduce data
    #pragma omp parallel for reduction(+:temp)
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            data[j][i] -= mean[i];
            temp = data[j][i] / sqrt(float_n * stddev[i]);
            symmat[j][i] = temp;
        }
    }

    // Compute pairwise correlations
    #pragma omp parallel for reduction(+:sum)
    for (i = 0; i < m; i++) {
        for (j = 0; j < i; j++) {
            sum = 0;
            for (k = 0; k < n; k++) {
                sum += data[k][i] * data[k][j];
            }
            symmat[i][j] = sum / (n - EPSILON);
        }
    }

    // Set diagonal elements to 1.0
    for (i = 0; i < m; i++) {
        symmat[i][i] = 1.0;
    }
