typedef double DATA_TYPE;

void kernel_cholesky(int n, DATA_TYPE *p, DATA_TYPE *A) {
    #pragma omp parallel for
    for (int i = 0; i < n; ++i) {
        double x = A[i * n + i];

        for (int j = 0; j <= i - 1; ++j) {
            x -= A[i * n + j] * A[i * n + j];
        }

        p[i] = 1.0 / sqrt(x);

        for (int j = i + 1; j < n; ++j) {
            double x = A[i * n + j];

            for (int k = 0; k <= i - 1; ++k) {
                x -= A[k * n + j] * A[i * n + k];
            }

            A[j * n + i] = x * p[i];
        }
    }
}

