void kernel_gramschmidt(int ni, int nj, DATA_TYPE *A, DATA_TYPE *R, DATA_TYPE *Q) {
    #pragma omp parallel for private(k, j, i, nrm, dot_product)
    for (k = 0; k < nj; ++k) {
        // Norm calculation
        nrm = 0;
        for (i = 0; i < ni; ++i) {
            nrm += A[i][k] * A[i][k];
        }
        R[k][k] = sqrt(nrm);

        // Normalization
        Q[0][k] = A[0][k] / R[k][k];

        // Orthogonalization against subsequent vectors
        for (j = k + 1; j < nj; ++j) {
            dot_product = 0;
            for (i = 0; i < ni; ++i) {
                dot_product += A[i][j] * Q[i][k];
            }
            R[k][j] = dot_product;

            for (i = 0; i < ni; ++i) {
                A[i][j] -= R[k][j] * Q[i][k];
            }
        }
    }
}

