// Define the data types
typedef double DATA_TYPE;

void kernel_durbin(int n, DATA_TYPE* y, DATA_TYPE* sum, DATA_TYPE* alpha, DATA_TYPE* beta, DATA_TYPE* r, DATA_TYPE* out) {
    // Initialize the first index of y with the first element of r
    y[0][0] = r[0];

    // Set the first elements of beta and alpha
    beta[0] = 0;
    alpha[0] = 1;

    // Parallel region for Durbin algorithm
#pragma omp parallel for
    for (int k = 1; k < n; ++k) {
        // Update beta
        beta[k] = beta[k-1] + alpha[k-1] * r[k];

        // Populate sum array
        sum[k][0] = r[k];
        for (int i = 0; i < k; ++i) {
            sum[k][i+1] = sum[k][i] + alpha[i] * r[k-i];
        }

        // Calculate new alpha
        alpha[k] = sum[k][k] / beta[k];

        // Update y
        for (int j = 0; j <= k; ++j) {
            y[j][k] = y[j][k-1] + alpha[k] * y[j][k-j];
        }
    }

    // Gather final coefficients from the last column of y
#pragma omp parallel for
    for (int k = 0; k < n; ++k) {
        out[k] = y[k][n-1];
    }
}

