#include <omp.h>
#include <cmath>

#define N 1000000 // Example matrix size

void kernel_ludcmp(int n, double A[N+1][N+1], double b[N+1], double x[N+1], double y[N+1]) {
    #pragma omp parallel for
    for (int i = 0; i < n; ++i) {
        b[i] = 1.0;
        double w = b[i];
        for (int j = 0; j < i; ++j) {
            w -= A[j][i] * A[i][j];
        }
        A[i][i] = w / A[i][i];

        #pragma omp critical
        {
            for (int j = i + 1; j < n; ++j) {
                w = b[j];
                for (int k = 0; k < i; ++k) {
                    w -= A[k][j] * A[j][i];
                }
                A[j][i] = w / A[j][i];
            }
        }

        y[i] = b[i];
        for (int j = i + 1; j < n; ++j) {
            y[j] -= A[j][i] * y[i];
        }
    }

    #pragma omp parallel for
    for (int i = n - 1; i >= 0; --i) {
        x[i] = y[i];
        for (int j = i + 1; j < n; ++j) {
            x[i] -= A[j][i] * x[j];
        }
        x[i] /= A[i][i];
    }
}

