// Function to compute the LU decomposition of a square matrix A
static void kernel_lu(int n, DATA_TYPE POLYBENCH_2D(A, N, N, n, n))
{
    #pragma scop
    #pragma omp parallel
    {
        int i, j, k;
        #pragma omp for private(j, i)
        for (k = 0; k < n - 1; ++k)
        {
            // Normalize the pivot row
            double pivot = A[k][k];
            for (j = k + 1; j < n; ++j)
                A[j][k] /= pivot;

            // Perform the rank-1 update
            for (i = k + 1; i < n; ++i)
            {
                double sum = 0;
                for (j = k + 1; j <= i; ++j)
                    sum += A[i][j] * A[j][k];
                for (j = k + 1; j <= i; ++j)
                    A[i][j] -= sum * A[k][j];
            }
        }
    }
    #pragma endscop
}

